#!/usr/bin/perl
# Differential tester: C++ test20_executable vs the Rust port.
#
#   difftest.pl <mode> <rounds> [seed]
#
# Modes: uniform extreme mixed tiny huge negative special ties hue strings all
# Each round feeds one batch of RGB triples to both binaries and compares
# stdout (and stderr) byte-for-byte.
use strict;
use warnings;

my $CPP  = "/workspace/dataset/test20_executable";
my $RUST = "/output/test20";

my ($mode, $rounds, $seed) = @ARGV;
$mode   //= "all";
$rounds //= 100;
$seed   //= 0;
srand($seed);

my @ALL = qw(uniform extreme mixed tiny huge negative special ties hue strings);

my @SPECIAL = (0, -0.0, 1, -1, 0.5, 2, -2, 1e-7, 255, 1/3, 2/3,
               0.9999999, 1.0000001, 1e-8, 3e-8, 0.25, 0.75, 1e-9);
my @STRINGS = (
    "0", "0.0", "-0", "-0.0", "1", "1.", ".5", "+.5", "  0.25", "0.5xyz",
    "1e-1", "1E-1", "0x1p-2", "0x.8p0", "0X1.4P1", "0x10p-5", "0x0p0",
    "inf", "-inf", "INF", "Infinity", "nan", "-nan", "NAN", "nan(0x1)",
    "1_0", "0.30000000000000004", "3.4028235e38", "1.1754944e-38",
    "0.1", "0.7", "12345678901234567890", "0.000001", "1e0", "5e-1", "-1e1",
    "0.9999999999999999", "1e-5", "0.0000001", "-0x1.8p-3", "+0", "  -0.5  ",
);

sub rnd { return rand(); }

sub gen {
    my ($m) = @_;
    if ($m eq "uniform")  { return rnd(); }
    if ($m eq "extreme")  { return $SPECIAL[int(rnd() * scalar @SPECIAL)]; }
    if ($m eq "mixed") {
        my $r = rnd();
        return rnd()                 if $r < 0.5;
        return rnd() * 5 - 2         if $r < 0.7;
        return $SPECIAL[int(rnd() * scalar @SPECIAL)] if $r < 0.85;
        return (rnd() * 2 - 1) * 1e6;
    }
    if ($m eq "tiny")     { return (rnd() < 0.5 ? -1 : 1) * 10 ** (-37 + rnd() * 32); }
    if ($m eq "huge")     { return (rnd() < 0.5 ? -1 : 1) * 10 ** (5 + rnd() * 32); }
    if ($m eq "negative") { return -rnd() * 5; }
    if ($m eq "ties")     { return (0.25, 0.5, 0.75, 0, 1, 0.5, 0.25)[int(rnd() * 7)]; }
    if ($m eq "hue") {
        # Hues that land on the hue2rgb sector boundaries (0/120/240/360).
        my @v = (0, 1, 0.5, rnd());
        return $v[int(rnd() * 4)];
    }
    return rnd();
}

sub spell {
    my ($m) = @_;
    return $STRINGS[int(rnd() * scalar @STRINGS)] if $m eq "strings";
    if ($m eq "special") {
        my @s = ("nan", "inf", "-inf", "0", "-0", "1", "0.5", "-0.5", "nan", "inf");
        return $s[int(rnd() * scalar @s)];
    }
    my $v = gen($m);
    my $style = rnd();
    return sprintf("%.17g", $v) if $style < 0.35;
    return sprintf("%.9g",  $v) if $style < 0.65;
    return sprintf("%.7f",  $v) if $style < 0.8;
    return sprintf("%e",    $v) if $style < 0.9;
    return sprintf("%.20g", $v);
}

sub run {
    my ($cmd, @args) = @_;
    my @q = map { my $s = $_; $s =~ s/'/'\\''/g; "'$s'" } @args;
    my $line = "$cmd " . join(" ", @q);
    my $out = `$line 2>/tmp/dt_err.$$`;
    my $rc = $?;
    local $/;
    open(my $fh, "<", "/tmp/dt_err.$$") or return ($rc, $out, "");
    my $err = <$fh>;
    close $fh;
    return ($rc, $out, defined($err) ? $err : "");
}

my $fails = 0;
my @modes = ($mode eq "all") ? @ALL : ($mode);

for my $it (1 .. $rounds) {
    my $m = $modes[int(rnd() * scalar @modes)];
    my $n = (1 + int(rnd() * 12)) * 3;
    my @args = map { spell($m) } (1 .. $n);

    my ($rc_c, $out_c, $err_c) = run($CPP,  @args);
    my ($rc_r, $out_r, $err_r) = run($RUST, @args);

    if ($out_c ne $out_r || $err_c ne $err_r) {
        $fails++;
        print "MISMATCH mode=$m iter=$it args=[" . join(" | ", @args) . "]\n";
        my @lc = split /\n/, $out_c;
        my @lr = split /\n/, $out_r;
        my $max = @lc > @lr ? @lc : @lr;
        for my $i (0 .. $max - 1) {
            my $a = $i < @lc ? $lc[$i] : "<missing>";
            my $b = $i < @lr ? $lr[$i] : "<missing>";
            next if $a eq $b;
            print "  cpp : $a\n  rust: $b\n";
            my @ta = split /\s+/, $a;
            my @tb = split /\s+/, $b;
            my $mx = @ta > @tb ? @ta : @tb;
            for my $j (0 .. $mx - 1) {
                my $x = $j < @ta ? $ta[$j] : "<>";
                my $y = $j < @tb ? $tb[$j] : "<>";
                print "    field $j: cpp=$x rust=$y\n" if $x ne $y;
            }
        }
        print "  stderr cpp=[$err_c] rust=[$err_r]\n" if $err_c ne $err_r;
        last if $fails >= 6;
    }
}
unlink "/tmp/dt_err.$$";
print "mode=$mode rounds=$rounds fails=$fails\n";
exit($fails ? 1 : 0);

//! Port of `dataset/color/tests/test20.cpp`.
//!
//! Prints, for a list of colours, every conversion the C++ test performed, with
//! `std::cout`'s default six-significant-digit formatting.

#[path = "src/color/mod.rs"]
mod color;

use std::io::Write;

use color::ostream::float_to_string as f;
use color::parse::{stof, StofError};
use color::{ColorConverter, RGB};

/// Reproduce what `std::terminate` does for an uncaught `std::stof` failure.
fn terminate(err: StofError) -> ! {
    eprint!(
        "terminate called after throwing an instance of '{}'\n  what():  stof\n",
        err.exception_name()
    );
    std::process::abort();
}

fn parse_arg(s: &str) -> f32 {
    match stof(s) {
        Ok(v) => v,
        Err(e) => terminate(e),
    }
}

fn main() {
    // `std::env::args()` panics on argv that is not valid UTF-8, while the C++
    // hands the raw bytes to `std::stof`, which stops at the first byte it
    // cannot use. Going through `args_os` and replacing the invalid bytes keeps
    // the two in step: a replacement character terminates the numeric prefix in
    // exactly the same place the original byte did.
    let args: Vec<String> = std::env::args_os()
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let argc = args.len() as i64;

    let mut colors: Vec<RGB> = Vec::new();

    // 添加一些默认颜色
    colors.push(RGB::new(0.1, 0.2, 0.3));
    colors.push(RGB::new(0.4, 0.5, 0.6));
    colors.push(RGB::new(0.7, 0.2, 0.1));
    colors.push(RGB::new(0.3, 0.8, 0.4));
    colors.push(RGB::new(0.9, 0.1, 0.8));

    // 从命令行参数添加更多颜色
    let mut i: i64 = 1;
    while i + 2 < argc {
        let r = parse_arg(&args[i as usize]);
        let g = parse_arg(&args[(i + 1) as usize]);
        let b = parse_arg(&args[(i + 2) as usize]);
        colors.push(RGB::new(r, g, b));
        i += 3;
    }

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());

    // 执行多个转换和操作
    for i in 0..colors.len() {
        let rgb = colors[i];

        // 基本转换
        let hsl = ColorConverter::rgb_to_hsl(rgb);
        let hsv = ColorConverter::rgb_to_hsv(rgb);
        let cmyk = ColorConverter::rgb_to_cmyk(rgb);
        let yuv = ColorConverter::rgb_to_yuv(rgb);

        // 亮度调整
        let bright = ColorConverter::adjust_brightness(rgb, 1.2);
        let dark = ColorConverter::adjust_brightness(rgb, 0.8);

        // 饱和度调整
        let saturated = ColorConverter::adjust_saturation(rgb, 1.5);

        // 灰度化
        let gray = ColorConverter::grayscale(rgb);

        // 反转
        let inverted = ColorConverter::invert(rgb);

        // 输出结果
        let mut line = String::with_capacity(256);
        line.push_str(&format!("Color {}: ", i));
        line.push_str(&format!("{} {} {} ", f(rgb.r), f(rgb.g), f(rgb.b)));
        line.push_str(&format!("{} {} {} ", f(hsl.h), f(hsl.s), f(hsl.l)));
        line.push_str(&format!("{} {} {} ", f(hsv.h), f(hsv.s), f(hsv.v)));
        line.push_str(&format!(
            "{} {} {} {} ",
            f(cmyk.c),
            f(cmyk.m),
            f(cmyk.y),
            f(cmyk.k)
        ));
        line.push_str(&format!("{} {} {} ", f(yuv.y), f(yuv.u), f(yuv.v)));
        line.push_str(&format!("{} {} {} ", f(bright.r), f(bright.g), f(bright.b)));
        line.push_str(&format!("{} {} {} ", f(dark.r), f(dark.g), f(dark.b)));
        line.push_str(&format!(
            "{} {} {} ",
            f(saturated.r),
            f(saturated.g),
            f(saturated.b)
        ));
        line.push_str(&format!("{} {} {} ", f(gray.r), f(gray.g), f(gray.b)));
        line.push_str(&format!(
            "{} {} {} ",
            f(inverted.r),
            f(inverted.g),
            f(inverted.b)
        ));

        // 如果是最后一个颜色，计算与第一个颜色的距离
        if i == colors.len() - 1 && colors.len() > 1 {
            let dist = ColorConverter::color_distance(rgb, colors[0]);
            line.push_str(&format!("{} ", f(dist)));
        }

        line.push('\n');
        out.write_all(line.as_bytes()).expect("stdout");
    }

    out.flush().expect("stdout");
}
