//! A `std`-only port of the C++ `ColorSpace` header used by the test suite.
//!
//! The re-exports below make up the public surface; a given binary only touches
//! part of it.
#![allow(unused_imports)]

pub mod converter;
pub mod ostream;
pub mod parse;
pub mod types;

pub use converter::ColorConverter;
pub use ostream::{double_to_string, float_to_string};
pub use parse::{stof, StofError};
pub use types::{CMYK, HSL, HSV, RGB, YUV};
=====TYPES=====
//! Plain colour-space value types, mirroring the C++ `ColorSpace` structs.
//!
//! Every component is an `f32` so that arithmetic rounds exactly the way the
//! original `float`-based C++ code does.

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct RGB {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl RGB {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        RGB { r, g, b }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct HSL {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl HSL {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        HSL { h, s, l }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct HSV {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

impl HSV {
    pub fn new(h: f32, s: f32, v: f32) -> Self {
        HSV { h, s, v }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct CMYK {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

impl CMYK {
    pub fn new(c: f32, m: f32, y: f32, k: f32) -> Self {
        CMYK { c, m, y, k }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct YUV {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl YUV {
    pub fn new(y: f32, u: f32, v: f32) -> Self {
        YUV { y, u, v }
    }
}

//! Colour-space conversions.
//!
//! Everything is deliberately written as single-precision expressions in the
//! same association order as the C++ original: the observable output is printed
//! with six significant digits, but values such as `0.615f*r - 0.515f*g -
//! 0.100f*b` for pure white land on `2.23517e-08` rather than `0`, so the
//! rounding of every intermediate matters.

use super::types::{CMYK, HSL, HSV, RGB, YUV};

/// `std::max(a, b)` — returns `a` when the comparison is unordered.
#[inline]
fn max2(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// `std::min(a, b)` — returns `a` when the comparison is unordered.
#[inline]
fn min2(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

/// `std::max(std::max(r, g), b)`
///
/// The association matters: `std::max` returns its *first* argument when the
/// comparison is unordered, so a NaN channel is swallowed or propagated
/// depending on where the fold starts.
#[inline]
fn max3(r: f32, g: f32, b: f32) -> f32 {
    max2(max2(r, g), b)
}

/// `std::min(std::min(r, g), b)`
#[inline]
fn min3(r: f32, g: f32, b: f32) -> f32 {
    min2(min2(r, g), b)
}

/// Clamp into `[0, 1]`; NaN propagates, matching `std::min(std::max(v, 0), 1)`.
#[inline]
fn clamp01(v: f32) -> f32 {
    min2(max2(v, 0.0), 1.0)
}

/// `a + b`, with `a`'s NaN surviving when both operands are NaN.
///
/// IEEE addition is commutative for every non-NaN input, so this pins down
/// exactly one thing: which NaN — and therefore which *sign* — comes out, since
/// `std::cout` prints `nan` or `-nan` accordingly. On x86 `addss` returns its
/// destination operand when both are NaN, and the C++ compiler's choice of
/// destination is what this reproduces.
#[inline]
fn add_keep_lhs_nan(a: f32, b: f32) -> f32 {
    if a.is_nan() {
        a
    } else if b.is_nan() {
        b
    } else {
        a + b
    }
}

/// `(t1 + t2) + t3` as the C++ compiler emitted the all-addition dot products:
/// the third product is the destination of the final add, so its NaN wins over
/// the first term's, which in turn wins over the second's. Bit-identical to a
/// plain left-to-right sum whenever no operand is NaN.
#[inline]
fn sum3(t1: f32, t2: f32, t3: f32) -> f32 {
    add_keep_lhs_nan(t3, add_keep_lhs_nan(t1, t2))
}

/// Hue sector of the max channel, in units of 60 degrees.
#[inline]
fn hue_sector(c: &RGB, max: f32, d: f32) -> f32 {
    if max == c.r {
        (c.g - c.b) / d + if c.g < c.b { 6.0 } else { 0.0 }
    } else if max == c.g {
        (c.b - c.r) / d + 2.0
    } else {
        (c.r - c.g) / d + 4.0
    }
}

/// Hue in degrees.
///
/// The sector is first normalised into `[0, 1]` and only then scaled to
/// degrees, exactly as the C++ does. The redundant `/6` followed by `*360` is
/// observable: it rounds twice, and `adjustSaturation` divides by 360 again and
/// amplifies the difference by up to `6*(q-p)`.
#[inline]
fn hue_degrees(c: &RGB, max: f32, d: f32) -> f32 {
    hue_sector(c, max, d) / 6.0 * 360.0
}


fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t < 1.0 / 6.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t < 1.0 / 2.0 {
        return q;
    }
    if t < 2.0 / 3.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(c: RGB) -> HSL {
        let max = max3(c.r, c.g, c.b);
        let min = min3(c.r, c.g, c.b);
        let l = (max + min) / 2.0;

        if max == min {
            return HSL::new(0.0, 0.0, l);
        }

        let d = max - min;
        let s = if l > 0.5 {
            d / (2.0 - max - min)
        } else {
            d / (max + min)
        };
        let h = hue_degrees(&c, max, d);
        HSL::new(h, s, l)
    }

    pub fn hsl_to_rgb(c: HSL) -> RGB {
        let h = c.h / 360.0;
        let s = c.s;
        let l = c.l;

        if s == 0.0 {
            return RGB::new(l, l, l);
        }

        let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
        let p = 2.0 * l - q;

        RGB::new(
            hue_to_rgb(p, q, h + 1.0 / 3.0),
            hue_to_rgb(p, q, h),
            hue_to_rgb(p, q, h - 1.0 / 3.0),
        )
    }

    pub fn rgb_to_hsv(c: RGB) -> HSV {
        let max = max3(c.r, c.g, c.b);
        let min = min3(c.r, c.g, c.b);
        let d = max - min;

        let v = max;
        let s = if max == 0.0 { 0.0 } else { d / max };
        let h = if max == min {
            0.0
        } else {
            hue_degrees(&c, max, d)
        };
        HSV::new(h, s, v)
    }

    pub fn rgb_to_cmyk(c: RGB) -> CMYK {
        let k = 1.0 - max3(c.r, c.g, c.b);
        if k == 1.0 {
            return CMYK::new(0.0, 0.0, 0.0, k);
        }
        CMYK::new(
            (1.0 - c.r - k) / (1.0 - k),
            (1.0 - c.g - k) / (1.0 - k),
            (1.0 - c.b - k) / (1.0 - k),
            k,
        )
    }

    pub fn rgb_to_yuv(c: RGB) -> YUV {
        // `u` and `v` contain subtractions, which the compiler cannot commute,
        // so there the running accumulator keeps its NaN.
        let y = sum3(0.299 * c.r, 0.587 * c.g, 0.114 * c.b);
        let u = add_keep_lhs_nan(-0.147 * c.r - 0.289 * c.g, 0.436 * c.b);
        let v = 0.615 * c.r - 0.515 * c.g - 0.100 * c.b;
        YUV::new(y, u, v)
    }

    pub fn adjust_brightness(c: RGB, factor: f32) -> RGB {
        RGB::new(
            clamp01(c.r * factor),
            clamp01(c.g * factor),
            clamp01(c.b * factor),
        )
    }

    pub fn adjust_saturation(c: RGB, factor: f32) -> RGB {
        let mut hsl = Self::rgb_to_hsl(c);
        hsl.s = clamp01(hsl.s * factor);
        Self::hsl_to_rgb(hsl)
    }

    pub fn grayscale(c: RGB) -> RGB {
        let gray = sum3(0.2126 * c.r, 0.7152 * c.g, 0.0722 * c.b);
        RGB::new(gray, gray, gray)
    }

    pub fn invert(c: RGB) -> RGB {
        RGB::new(1.0 - c.r, 1.0 - c.g, 1.0 - c.b)
    }

    pub fn color_distance(a: RGB, b: RGB) -> f32 {
        let dr = a.r - b.r;
        let dg = a.g - b.g;
        let db = a.b - b.b;
        sum3(dr * dr, dg * dg, db * db).sqrt()
    }
}

//! Reproduction of `std::ostream`'s default floating-point formatting.
//!
//! `std::cout << some_float` promotes the `float` to `double` and then formats
//! it exactly like `printf("%g")` with the default stream precision of 6, i.e.
//! six *significant* digits, trailing zeros stripped, and a switch to
//! scientific notation when the decimal exponent leaves `[-4, 6)`.

/// Default `std::ios_base::precision()`.
const PRECISION: i32 = 6;

/// Format an `f32` the way `std::cout << value` would (via promotion to
/// `double`).
pub fn float_to_string(v: f32) -> String {
    double_to_string(v as f64)
}

/// Format an `f64` the way `std::cout << value` would.
pub fn double_to_string(v: f64) -> String {
    if v.is_nan() {
        // glibc prints the sign bit of a NaN, and so does libstdc++.
        return if v.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }
    if v.is_infinite() {
        return if v.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    // C99 %g: let X be the exponent of the value converted in style `e` with
    // precision P-1. Style `f` is used when -4 <= X < P, otherwise style `e`.
    let sci = format!("{:.*e}", (PRECISION - 1) as usize, v);
    let e_pos = sci.find('e').expect("exponential form always has an 'e'");
    let exp: i32 = sci[e_pos + 1..]
        .parse()
        .expect("exponent is always a decimal integer");

    if exp < -4 || exp >= PRECISION {
        let mantissa = strip_trailing_zeros(&sci[..e_pos]);
        let sign = if exp < 0 { '-' } else { '+' };
        // The exponent always carries a sign and at least two digits.
        format!("{}e{}{:02}", mantissa, sign, exp.unsigned_abs())
    } else {
        let fixed = format!("{:.*}", (PRECISION - 1 - exp) as usize, v);
        strip_trailing_zeros(&fixed).to_string()
    }
}

/// Drop the trailing zeros (and then a bare trailing point) of a decimal
/// fraction, as `%g` does without the `#` flag.
fn strip_trailing_zeros(s: &str) -> &str {
    if !s.contains('.') {
        return s;
    }
    let s = s.trim_end_matches('0');
    s.strip_suffix('.').unwrap_or(s)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_cout_defaults() {
        assert_eq!(float_to_string(0.1), "0.1");
        assert_eq!(float_to_string(2.0 / 3.0), "0.666667");
        assert_eq!(float_to_string(0.18596), "0.18596");
        assert_eq!(float_to_string(307.5), "307.5");
        assert_eq!(float_to_string(3.5762787e-07), "3.57628e-07");
        assert_eq!(float_to_string(2.2351742e-08), "2.23517e-08");
        assert_eq!(float_to_string(1e10), "1e+10");
        assert_eq!(float_to_string(-1e10), "-1e+10");
        assert_eq!(float_to_string(0.0), "0");
        assert_eq!(float_to_string(-0.0), "-0");
        assert_eq!(float_to_string(f32::INFINITY), "inf");
        assert_eq!(float_to_string(-f32::INFINITY), "-inf");
        assert_eq!(float_to_string(f32::NAN), "nan");
        assert_eq!(float_to_string(-f32::NAN), "-nan");
        assert_eq!(float_to_string(1.2e-10), "1.2e-10");
        assert_eq!(float_to_string(1e-5), "1e-05");
        assert_eq!(float_to_string(1e-4), "0.0001");
        assert_eq!(float_to_string(123456.0), "123456");
        assert_eq!(float_to_string(1234567.0), "1.23457e+06");
    }
}

//! A faithful re-implementation of `std::stof`.
//!
//! `std::stof` is a thin wrapper over C's `strtof`: it skips leading
//! whitespace, accepts decimal, hexadecimal, `inf[inity]` and `nan[(chars)]`
//! forms, ignores any trailing garbage, throws `std::invalid_argument` when no
//! conversion could be performed and `std::out_of_range` when `strtof` reports
//! `ERANGE` (overflow, or a result that underflows below `FLT_MIN`).

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// Nothing convertible at the head of the string.
    Invalid,
    /// `strtof` set `ERANGE`.
    OutOfRange,
}

impl StofError {
    /// The C++ exception class name, as printed by `std::terminate`.
    pub fn exception_name(self) -> &'static str {
        match self {
            StofError::Invalid => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
}

pub fn stof(s: &str) -> Result<f32, StofError> {
    match strtof(s.as_bytes()) {
        None => Err(StofError::Invalid),
        Some(Parsed { erange: true, .. }) => Err(StofError::OutOfRange),
        Some(Parsed { value, .. }) => Ok(value),
    }
}

struct Parsed {
    value: f32,
    erange: bool,
}

#[inline]
fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

#[inline]
fn lower(b: u8) -> u8 {
    b | 0x20
}

fn starts_with_ci(s: &[u8], word: &[u8]) -> bool {
    s.len() >= word.len() && s[..word.len()].iter().zip(word).all(|(a, b)| lower(*a) == *b)
}

/// `strtof`, minus the `endptr` output (the caller never inspects it).
/// Returns `None` when no conversion could be performed.
fn strtof(s: &[u8]) -> Option<Parsed> {
    let mut i = 0;
    while i < s.len() && is_space(s[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        negative = s[i] == b'-';
        i += 1;
    }
    let rest = &s[i..];

    if starts_with_ci(rest, b"infinity") || starts_with_ci(rest, b"inf") {
        let v = if negative {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        };
        return Some(Parsed {
            value: v,
            erange: false,
        });
    }
    if starts_with_ci(rest, b"nan") {
        let v = if negative { -f32::NAN } else { f32::NAN };
        return Some(Parsed {
            value: v,
            erange: false,
        });
    }

    if rest.len() >= 2 && rest[0] == b'0' && lower(rest[1]) == b'x' {
        if let Some(p) = parse_hex(&rest[2..], negative) {
            return Some(p);
        }
        // "0x" with no hex digits: the longest valid prefix is just "0".
        return Some(Parsed {
            value: if negative { -0.0 } else { 0.0 },
            erange: false,
        });
    }

    parse_decimal(rest, negative)
}

/// Split off a run of ASCII digits.
fn take_digits(s: &[u8]) -> (&[u8], &[u8]) {
    let n = s.iter().take_while(|b| b.is_ascii_digit()).count();
    (&s[..n], &s[n..])
}

/// Parse the optional `e[+-]ddd` / `p[+-]ddd` suffix. Returns the exponent and
/// the remainder; the suffix is only consumed when at least one digit follows.
fn take_exponent(s: &[u8], marker: u8) -> i64 {
    if s.is_empty() || lower(s[0]) != marker {
        return 0;
    }
    let mut j = 1;
    let mut neg = false;
    if j < s.len() && (s[j] == b'+' || s[j] == b'-') {
        neg = s[j] == b'-';
        j += 1;
    }
    let (digits, _) = take_digits(&s[j..]);
    if digits.is_empty() {
        return 0;
    }
    // Saturate: anything beyond a few hundred is already ±inf or 0.
    let mut exp: i64 = 0;
    for d in digits {
        exp = exp * 10 + i64::from(d - b'0');
        if exp > 1_000_000 {
            break;
        }
    }
    if neg {
        -exp
    } else {
        exp
    }
}

fn parse_decimal(s: &[u8], negative: bool) -> Option<Parsed> {
    let (int_digits, after_int) = take_digits(s);
    let (frac_digits, after_frac) = if !after_int.is_empty() && after_int[0] == b'.' {
        take_digits(&after_int[1..])
    } else {
        (&after_int[..0], after_int)
    };
    if int_digits.is_empty() && frac_digits.is_empty() {
        return None;
    }

    let exp = take_exponent(after_frac, b'e');

    // Hand the normalised literal to the standard library, which converts
    // decimal to `f32` with correct rounding.
    let mut literal = String::with_capacity(int_digits.len() + frac_digits.len() + 24);
    literal.push_str(std::str::from_utf8(int_digits).unwrap_or("0"));
    literal.push('.');
    literal.push_str(std::str::from_utf8(frac_digits).unwrap_or("0"));
    if literal.starts_with('.') {
        literal.insert(0, '0');
    }
    if literal.ends_with('.') {
        literal.push('0');
    }
    let exp = exp.clamp(-1_000_000, 1_000_000);
    literal.push('e');
    literal.push_str(&exp.to_string());

    let magnitude: f32 = literal.parse().unwrap_or(0.0);
    let all_zero = int_digits.iter().chain(frac_digits).all(|d| *d == b'0');
    Some(finish(magnitude, negative, all_zero))
}

/// Split off a run of ASCII hex digits.
fn take_hex_digits(s: &[u8]) -> (&[u8], &[u8]) {
    let n = s.iter().take_while(|b| b.is_ascii_hexdigit()).count();
    (&s[..n], &s[n..])
}

fn parse_hex(s: &[u8], negative: bool) -> Option<Parsed> {
    let hex_run = take_hex_digits;

    let (int_digits, after_int) = hex_run(s);
    let (frac_digits, after_frac) = if !after_int.is_empty() && after_int[0] == b'.' {
        hex_run(&after_int[1..])
    } else {
        (&after_int[..0], after_int)
    };
    if int_digits.is_empty() && frac_digits.is_empty() {
        return None;
    }

    let p_exp = take_exponent(after_frac, b'p');

    // value == mantissa * 2^exp2, with `mantissa` the concatenated hex digits.
    let significant: Vec<u8> = int_digits
        .iter()
        .chain(frac_digits)
        .map(|b| hex_value(*b))
        .skip_while(|d| *d == 0)
        .collect();
    let exp2 = p_exp - 4 * frac_digits.len() as i64;

    if significant.is_empty() {
        return Some(Parsed {
            value: if negative { -0.0 } else { 0.0 },
            erange: false,
        });
    }

    // Short-circuit magnitudes that cannot possibly round into range, so the
    // exact expansion below never has to chew through a huge exponent.
    let approx_log2 = 4 * significant.len() as i64 + exp2;
    if approx_log2 > 160 {
        return Some(finish(f32::INFINITY, negative, false));
    }
    if approx_log2 < -200 {
        return Some(finish(0.0, negative, false));
    }

    // Exact decimal expansion: m * 2^e == (m * 5^-e) * 10^e for e < 0.
    let mut digits = BigDec::zero();
    for d in &significant {
        digits.mul_add_small(16, u32::from(*d));
    }
    let dec_exp = if exp2 >= 0 {
        for _ in 0..exp2 {
            digits.mul_add_small(2, 0);
        }
        0
    } else {
        for _ in 0..-exp2 {
            digits.mul_add_small(5, 0);
        }
        exp2
    };

    let literal = format!("{}e{}", digits, dec_exp);
    let magnitude: f32 = literal.parse().unwrap_or(0.0);
    Some(finish(magnitude, negative, false))
}

/// Apply the sign and decide whether `strtof` would have set `ERANGE`.
fn finish(magnitude: f32, negative: bool, all_zero: bool) -> Parsed {
    let erange = if magnitude.is_infinite() {
        true
    } else {
        // glibc reports underflow for any non-zero input that lands on zero or
        // on a subnormal.
        !all_zero && magnitude < f32::MIN_POSITIVE
    };
    Parsed {
        value: if negative { -magnitude } else { magnitude },
        erange,
    }
}

fn hex_value(b: u8) -> u8 {
    match b {
        b'0'..=b'9' => b - b'0',
        _ => lower(b) - b'a' + 10,
    }
}

/// A minimal big decimal integer: just enough to expand a hex significand.
struct BigDec {
    /// Little-endian decimal digits; empty means zero.
    digits: Vec<u8>,
}

impl BigDec {
    fn zero() -> Self {
        BigDec { digits: Vec::new() }
    }

    fn mul_add_small(&mut self, mul: u32, add: u32) {
        let mut carry = add;
        for d in self.digits.iter_mut() {
            let v = u32::from(*d) * mul + carry;
            *d = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            self.digits.push((carry % 10) as u8);
            carry /= 10;
        }
    }
}

impl std::fmt::Display for BigDec {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.digits.is_empty() {
            return f.write_str("0");
        }
        for d in self.digits.iter().rev() {
            write!(f, "{}", d)?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_what_strtof_accepts() {
        assert_eq!(stof("0.5"), Ok(0.5));
        assert_eq!(stof(".5"), Ok(0.5));
        assert_eq!(stof("+3"), Ok(3.0));
        assert_eq!(stof("-.5e1"), Ok(-5.0));
        assert_eq!(stof("1abc"), Ok(1.0));
        assert_eq!(stof("  1.5xyz"), Ok(1.5));
        assert_eq!(stof("1_0"), Ok(1.0));
        assert_eq!(stof("0x1p4"), Ok(16.0));
        assert_eq!(stof("0x1.8p1"), Ok(3.0));
        assert_eq!(stof("INFINITY"), Ok(f32::INFINITY));
        assert!(stof("nan(123)").unwrap().is_nan());
        assert_eq!(stof("3.4e38"), Ok(3.4e38));
    }

    #[test]
    fn rejects_what_strtof_rejects() {
        assert_eq!(stof("abc"), Err(StofError::Invalid));
        assert_eq!(stof(""), Err(StofError::Invalid));
        assert_eq!(stof("e5"), Err(StofError::Invalid));
        assert_eq!(stof("1e999"), Err(StofError::OutOfRange));
        assert_eq!(stof("1e-999"), Err(StofError::OutOfRange));
        assert_eq!(stof("1e-46"), Err(StofError::OutOfRange));
        assert_eq!(stof("1e-44"), Err(StofError::OutOfRange));
        assert_eq!(stof("3.5e38"), Err(StofError::OutOfRange));
        assert_eq!(stof("0.0"), Ok(0.0));
    }
}
